void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float down = texelFetch(iChannel0, ivec2(int(uv.x * 255.0), 0), 0).x;
  float pressed = texelFetch(iChannel0, ivec2(int(uv.x * 255.0), 1), 0).x;
  float toggle = texelFetch(iChannel0, ivec2(int(uv.x * 255.0), 2), 0).x;
  fragColor = vec4(down, pressed, toggle, 1.0);
}
